'use strict';

function touchAssetCache(cache, key, payload, capacity) {
  if (cache === null || typeof cache !== 'object' || Array.isArray(cache) ||
      !Array.isArray(cache.order) || cache.entries === null ||
      typeof cache.entries !== 'object' || Array.isArray(cache.entries) ||
      typeof key !== 'string' || key.length === 0 ||
      !Number.isSafeInteger(capacity) || capacity < 0) {
    throw new TypeError('invalid cache arguments');
  }

  const ownKeys = Object.keys(cache.entries);
  const seen = new Set();
  for (const item of cache.order) {
    if (typeof item !== 'string' || item.length === 0 || seen.has(item) ||
        !Object.prototype.hasOwnProperty.call(cache.entries, item)) {
      throw new TypeError('invalid cache');
    }
    seen.add(item);
  }
  if (ownKeys.length !== seen.size || ownKeys.some(item => !seen.has(item))) {
    throw new TypeError('invalid cache');
  }

  const order = cache.order.filter(item => item !== key);
  const entries = Object.assign({}, cache.entries, { [key]: payload });
  order.push(key);
  while (order.length > capacity) {
    const evicted = order.pop();
    delete entries[evicted];
  }
  return { order, entries };
}

module.exports = { touchAssetCache };
