'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['touchAssetCache']);
const { touchAssetCache } = api;

const payloadA = { asset: 'a' };
const payloadB = { asset: 'b' };
const cache = { order: ['a', 'b'], entries: { a: payloadA, b: payloadB } };
const beforeOrder = cache.order.slice();
const replacement = { asset: 'new-a' };
const touched = touchAssetCache(cache, 'a', replacement, 2);
assert.deepStrictEqual(touched.order, ['b', 'a']);
assert.strictEqual(touched.entries.a, replacement);
assert.strictEqual(touched.entries.b, payloadB);
assert.notStrictEqual(touched, cache);
assert.notStrictEqual(touched.order, cache.order);
assert.notStrictEqual(touched.entries, cache.entries);
assert.deepStrictEqual(cache.order, beforeOrder);
assert.strictEqual(cache.entries.a, payloadA);

const payloadC = { asset: 'c' };
const evicted = touchAssetCache(cache, 'c', payloadC, 2);
assert.deepStrictEqual(evicted.order, ['b', 'c']);
assert.deepStrictEqual(Object.keys(evicted.entries).sort(), ['b', 'c']);
assert.strictEqual(evicted.entries.b, payloadB);
assert.strictEqual(evicted.entries.c, payloadC);
assert.strictEqual(Object.prototype.hasOwnProperty.call(evicted.entries, 'a'), false);
const zero = touchAssetCache(cache, 'c', payloadC, 0);
assert.deepStrictEqual(zero.order, []);
assert.deepStrictEqual(Object.keys(zero.entries), []);
const undefinedPayload = touchAssetCache({ order: [], entries: {} }, 'x', undefined, 1);
assert.deepStrictEqual(undefinedPayload.order, ['x']);
assert.strictEqual(Object.prototype.hasOwnProperty.call(undefinedPayload.entries, 'x'), true);
assert.strictEqual(undefinedPayload.entries.x, undefined);

for (const args of [
  [null, 'x', 1, 1],
  [{}, 'x', 1, 1],
  [{ order: [], entries: [] }, 'x', 1, 1],
  [{ order: [''], entries: { '': 1 } }, 'x', 1, 1],
  [{ order: ['a', 'a'], entries: { a: 1 } }, 'x', 1, 1],
  [{ order: ['a'], entries: {} }, 'x', 1, 1],
  [{ order: [], entries: { a: 1 } }, 'x', 1, 1],
  [{ order: [], entries: {} }, '', 1, 1],
  [{ order: [], entries: {} }, 2, 1, 1],
  [{ order: [], entries: {} }, 'x', 1, -1],
  [{ order: [], entries: {} }, 'x', 1, 1.5]
]) {
  assert.throws(() => touchAssetCache(...args), TypeError);
}

